package main

import (
	"os"
	"testing"
)

func TestCheckDocs(t *testing.T) {
	// The transcripts are generated by the acceptance suite and are not
	// committed (ADR 0027 D5). `go test ./...` runs the packages in parallel, so
	// on a fresh checkout they may not exist yet; `make docs` generates them
	// first and then runs this check for real.
	if _, err := os.Stat("../../site/data/transcripts"); err != nil {
		t.Skip("transcripts not generated; run `make docs`")
	}

	if err := checkTranscripts("../../site/data/transcripts"); err != nil {
		t.Fatalf("checkTranscripts failed: %v", err)
	}

	if err := checkContent("../../site/content", "../../site/data/transcripts"); err != nil {
		t.Fatalf("checkContent failed: %v", err)
	}
}
